files.content:
.style-karan {
  /* MARK: Contextual Surface & Intent Layering */
  [data-slot="card"][data-intent="primary"],
  [data-slot="alert"][data-intent="primary"] {
    --neutral-surface: var(--primary-surface);
    --neutral-surface-alt: var(--primary-surface-alt);
    --neutral-fill: var(--primary-fill);
    --neutral-fill-hover: var(--primary-fill-hover);
    --neutral-fill-active: var(--primary-fill-active);
    --neutral-text: var(--primary-text);
    --neutral-text-secondary: var(--primary-text-secondary);
    --neutral-text-muted: var(--primary-text-muted);
    --neutral-on-fill: var(--primary-on-fill);
    --neutral-interactive-focus: var(--primary-interactive-focus);
    --neutral-interactive-active: var(--primary-interactive-active);
  }

  [data-slot="card"][data-intent="info"],
  [data-slot="alert"][data-intent="info"] {
    --neutral-surface: var(--info-surface);
    --neutral-surface-alt: var(--info-surface-alt);
    --neutral-fill: var(--info-fill);
    --neutral-fill-hover: var(--info-fill-hover);
    --neutral-fill-active: var(--info-fill-active);
    --neutral-text: var(--info-text);
    --neutral-text-secondary: var(--info-text-secondary);
    --neutral-text-muted: var(--info-text-muted);
    --neutral-on-fill: var(--info-on-fill);
    --neutral-interactive-focus: var(--info-interactive-focus);
    --neutral-interactive-active: var(--info-interactive-active);
  }

  [data-slot="card"][data-intent="success"],
  [data-slot="alert"][data-intent="success"] {
    --neutral-surface: var(--success-surface);
    --neutral-surface-alt: var(--success-surface-alt);
    --neutral-fill: var(--success-fill);
    --neutral-fill-hover: var(--success-fill-hover);
    --neutral-fill-active: var(--success-fill-active);
    --neutral-text: var(--success-text);
    --neutral-text-secondary: var(--success-text-secondary);
    --neutral-text-muted: var(--success-text-muted);
    --neutral-on-fill: var(--success-on-fill);
    --neutral-interactive-focus: var(--success-interactive-focus);
    --neutral-interactive-active: var(--success-interactive-active);
  }

  [data-slot="card"][data-intent="warning"],
  [data-slot="alert"][data-intent="warning"] {
    --neutral-surface: var(--warning-surface);
    --neutral-surface-alt: var(--warning-surface-alt);
    --neutral-fill: var(--warning-fill);
    --neutral-fill-hover: var(--warning-fill-hover);
    --neutral-fill-active: var(--warning-fill-active);
    --neutral-text: var(--warning-text);
    --neutral-text-secondary: var(--warning-text-secondary);
    --neutral-text-muted: var(--warning-text-muted);
    --neutral-on-fill: var(--warning-on-fill);
    --neutral-interactive-focus: var(--warning-interactive-focus);
    --neutral-interactive-active: var(--warning-interactive-active);
  }

  [data-slot="card"][data-intent="danger"],
  [data-slot="alert"][data-intent="danger"],
  [data-slot="alert"][data-variant="destructive"] {
    --neutral-surface: var(--danger-surface);
    --neutral-surface-alt: var(--danger-surface-alt);
    --neutral-fill: var(--danger-fill);
    --neutral-fill-hover: var(--danger-fill-hover);
    --neutral-fill-active: var(--danger-fill-active);
    --neutral-text: var(--danger-text);
    --neutral-text-secondary: var(--danger-text-secondary);
    --neutral-text-muted: var(--danger-text-muted);
    --neutral-on-fill: var(--danger-on-fill);
    --neutral-interactive-focus: var(--danger-interactive-focus);
    --neutral-interactive-active: var(--danger-interactive-active);
  }

  .cn-alert,
  .cn-command,
  .cn-sidebar-inner {
    --current-surface: var(--neutral-surface-alt);
  }

  .cn-alert-dialog-content,
  .cn-alert-dialog-content-aria,
  .cn-dialog-content,
  .cn-dialog-content-aria,
  .cn-drawer-popup,
  .cn-drawer-content,
  .cn-sheet-content,
  .cn-popover-content,
  .cn-popover-content-aria,
  .cn-hover-card-content,
  .cn-hover-card-content-aria,
  .cn-select-content,
  .cn-select-content-aria,
  .cn-combobox-content,
  .cn-combobox-content-aria,
  .cn-dropdown-menu-content,
  .cn-dropdown-menu-content-aria,
  .cn-dropdown-menu-sub-content,
  .cn-dropdown-menu-sub-content-aria,
  .cn-context-menu-content,
  .cn-context-menu-content-aria,
  .cn-context-menu-sub-content,
  .cn-context-menu-sub-content-aria,
  .cn-menubar-content,
  .cn-menubar-sub-content,
  .cn-navigation-menu-popup,
  .cn-navigation-menu-viewport,
  .cn-chart-tooltip {
    --current-surface: var(--neutral-surface);
    &:is(.dark *) {
      --current-surface: var(--neutral-surface-alt);
    }
  }

  /* MARK: Slider */
  .cn-slider {
    @apply w-full data-[orientation=vertical]:min-h-40;
  }

  .cn-slider-track {
    @apply bg-neutral-interactive rounded-full h-2 w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-2 relative grow overflow-hidden;
  }

  .cn-slider-range {
    @apply bg-primary-fill h-full data-[orientation=vertical]:w-full transition-[width,height,inset-inline-start,bottom] duration-150 ease-[cubic-bezier(0.22,1,0.36,1)] data-dragging:transition-none group-data-dragging/slider:transition-none;
  }

  .cn-slider-thumb {
    @apply ring-1 ring-black/10 dark:ring-white/20 size-5 rounded-full bg-neutral-surface border-2 border-primary-fill shadow-md transition-[inset-inline-start,bottom,box-shadow,background-color,border-color] duration-150 ease-[cubic-bezier(0.22,1,0.36,1)] data-dragging:transition-[box-shadow,background-color,border-color] group-data-dragging/slider:transition-[box-shadow,background-color,border-color] hover:ring-4 hover:ring-primary-interactive-focus/30 focus-visible:ring-4 focus-visible:ring-primary-interactive-focus/30 focus-visible:outline-hidden active:ring-4 active:ring-primary-interactive-focus/40 cursor-grab active:cursor-grabbing data-[orientation=vertical]:size-5;
  }

  .cn-slider-tooltip {
    @apply bg-neutral-text text-neutral-surface rounded-sm px-2 py-0.5 font-mono text-[11px] leading-tight font-medium tabular-nums shadow-sm;
  }

  .cn-slider-tooltip-arrow {
    @apply bg-neutral-text size-2 rotate-45 rounded-[1px];
  }

  /* MARK: Switch */
  .cn-switch {
    @apply data-checked:bg-primary-fill data-unchecked:bg-neutral-interactive data-checked:border-primary-fill border-2 data-unchecked:border-transparent focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/50 shrink-0 rounded-full focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:data-unchecked:border-transparent group-has-[:focus-visible]/field-label:data-checked:border-primary-fill data-[size=default]:h-5 data-[size=default]:w-11 data-[size=sm]:h-4 data-[size=sm]:w-7;
  }

  .cn-switch-aria {
    @apply data-selected:bg-primary-fill not-data-selected:bg-neutral-interactive data-selected:border-primary-fill not-data-selected:border-transparent data-focus-visible:border-primary-interactive-focus data-focus-visible:ring-primary-interactive-focus/30 data-focus-visible:ring-3 data-invalid:ring-danger-interactive-focus/20 dark:data-invalid:ring-danger-interactive-focus/40 data-invalid:border-danger-fill dark:data-invalid:border-danger-fill/50 data-invalid:ring-3;
  }

  .cn-switch-thumb {
    @apply bg-neutral-surface dark:data-unchecked:bg-neutral-text dark:data-checked:bg-primary-on-fill rounded-full shadow-sm group-data-[size=default]/switch:h-4 group-data-[size=default]/switch:w-6 group-data-[size=sm]/switch:h-3 group-data-[size=sm]/switch:w-4 data-checked:translate-x-[calc(100%-8px)] data-unchecked:translate-x-0 not-dark:bg-clip-padding;
  }

  .cn-switch-thumb-aria {
    @apply dark:not-data-selected:bg-neutral-text dark:data-selected:bg-primary-on-fill data-selected:translate-x-[calc(100%-8px)] not-data-selected:translate-x-0;
  }

  /* MARK: Radio */
  .cn-radio-group {
    @apply grid gap-3 data-[orientation=horizontal]:flex data-[orientation=horizontal]:flex-row data-[orientation=horizontal]:flex-wrap data-[orientation=horizontal]:items-center data-[orientation=horizontal]:gap-4;
  }

  .cn-radio-group-item {
    @apply aria-invalid:border-danger-fill focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 dark:aria-invalid:border-danger-fill/50 transition-[background-color,border-color,color,box-shadow,transform] duration-150 ease-[cubic-bezier(0.22,1,0.36,1)] focus-visible:ring-3 aria-invalid:ring-3 not-data-custom:bg-neutral-interactive not-data-custom:hover:bg-neutral-interactive-hover not-data-custom:data-checked:bg-primary-fill not-data-custom:data-checked:hover:bg-primary-fill-hover not-data-custom:data-checked:text-primary-on-fill dark:not-data-custom:data-checked:bg-primary-fill not-data-custom:border-transparent not-data-custom:data-checked:border-primary-fill not-data-custom:flex not-data-custom:size-4 not-data-custom:items-center not-data-custom:justify-center not-data-custom:rounded-full not-data-custom:group-has-[:focus-visible]/field-label:ring-0 not-data-custom:group-has-[:focus-visible]/field-label:border-transparent data-custom:border-neutral-interactive data-custom:bg-neutral-surface data-custom:hover:border-neutral-interactive-hover data-custom:hover:bg-neutral-interactive/35 data-custom:data-checked:border-primary-fill data-custom:data-checked:bg-primary-surface/35 data-custom:data-checked:ring-1 data-custom:data-checked:ring-primary-fill;
  }

  .cn-radio-group-item-aria {
    @apply data-selected:bg-primary-fill data-selected:text-primary-on-fill dark:data-selected:bg-primary-fill data-focus-visible:border-primary-interactive-focus data-focus-visible:ring-primary-interactive-focus/30 data-focus-visible:ring-3 data-invalid:border-danger-fill data-invalid:ring-danger-interactive-focus/20 dark:data-invalid:ring-danger-interactive-focus/40 dark:data-invalid:border-danger-fill/50 data-invalid:ring-3;
  }

  .cn-radio-group-indicator {
    @apply relative flex size-4 items-center justify-center;
  }

  .cn-radio-group-indicator-icon {
    @apply bg-primary-on-fill pointer-events-none absolute inset-0 m-auto size-2 scale-0 rounded-full opacity-0 transition-[transform,opacity] duration-150 ease-[cubic-bezier(0.16,1,0.3,1)] group-data-checked/radio-group-item:scale-100 group-data-checked/radio-group-item:opacity-100 in-data-checked:scale-100 in-data-checked:opacity-100 dark:size-2;
  }

  /* MARK: Checkbox */
  .cn-checkbox {
    @apply bg-neutral-interactive hover:bg-neutral-interactive-hover data-checked:bg-primary-fill data-checked:hover:bg-primary-fill-hover data-checked:text-primary-on-fill dark:data-checked:bg-primary-fill data-checked:border-primary-fill data-indeterminate:bg-primary-fill data-indeterminate:hover:bg-primary-fill-hover data-indeterminate:text-primary-on-fill dark:data-indeterminate:bg-primary-fill data-indeterminate:border-primary-fill border-transparent aria-invalid:aria-checked:border-primary-fill aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/50 focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 flex size-4 items-center justify-center rounded-[5px] border transition-[background-color,border-color,color,box-shadow,transform] duration-150 ease-[cubic-bezier(0.22,1,0.36,1)] group-has-disabled/field:opacity-50 focus-visible:ring-3 aria-invalid:ring-3 group-has-[:focus-visible]/field-label:ring-0 group-has-[:focus-visible]/field-label:not-data-checked:not-data-indeterminate:border-transparent group-has-[:focus-visible]/field-label:data-checked:border-primary-fill group-has-[:focus-visible]/field-label:data-indeterminate:border-primary-fill;
  }

  .cn-checkbox-aria {
    @apply data-selected:bg-primary-fill data-selected:text-primary-on-fill dark:data-selected:bg-primary-fill data-selected:border-primary-fill data-indeterminate:bg-primary-fill data-indeterminate:text-primary-on-fill dark:data-indeterminate:bg-primary-fill data-indeterminate:border-primary-fill data-focus-visible:border-primary-interactive-focus data-focus-visible:ring-primary-interactive-focus/30 data-focus-visible:ring-3 data-invalid:data-selected:border-primary-fill data-invalid:border-danger-fill dark:data-invalid:border-danger-fill/50 data-invalid:ring-danger-interactive-focus/20 dark:data-invalid:ring-danger-interactive-focus/40 data-invalid:ring-3;
  }

  .cn-checkbox-indicator {
    @apply [&>svg]:size-3;
  }

  .cn-checkbox-group {
    @apply flex flex-col gap-2.5;
  }

  /* MARK: Button */
  .cn-button {
    @apply focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/50 border border-transparent bg-clip-padding font-medium transition-[background-color,color,border-color,box-shadow] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] focus-visible:ring-3 aria-invalid:ring-3;
  }

  .cn-button-variant-default {
    @apply bg-primary-fill text-primary-on-fill hover:bg-primary-fill-hover active:bg-primary-fill-active [&[data-pressed]]:bg-primary-fill-active;
  }

  .cn-button-variant-outline {
    @apply border-neutral-interactive bg-neutral-surface text-neutral-text dark:bg-transparent hover:bg-neutral-interactive dark:hover:bg-neutral-interactive hover:text-neutral-text active:bg-neutral-interactive-hover dark:active:bg-neutral-interactive-hover [&[data-pressed]]:bg-neutral-interactive-hover dark:[&[data-pressed]]:bg-neutral-interactive-hover aria-expanded:bg-neutral-interactive dark:aria-expanded:bg-neutral-interactive aria-expanded:text-neutral-text;
  }

  .cn-button-variant-secondary {
    @apply bg-neutral-interactive text-neutral-text hover:bg-neutral-interactive-hover active:bg-neutral-interactive-active [&[data-pressed]]:bg-neutral-interactive-active aria-expanded:bg-neutral-interactive aria-expanded:text-neutral-text;
  }

  .cn-button-variant-ghost {
    @apply bg-transparent text-neutral-text hover:bg-neutral-interactive hover:text-neutral-text active:bg-neutral-interactive-hover [&[data-pressed]]:bg-neutral-interactive-hover aria-expanded:bg-neutral-interactive aria-expanded:text-neutral-text;
  }

  .cn-button-variant-link {
    @apply bg-transparent text-neutral-text-secondary underline-offset-4 hover:text-neutral-text hover:underline focus-visible:text-neutral-text focus-visible:underline active:text-neutral-text-secondary [&[data-pressed]]:text-neutral-text-secondary;
  }

  .cn-button-size-xs {
    @apply h-6 gap-1 rounded-md px-2 text-xs [&_svg:not([class*='size-'])]:size-3;
  }

  .cn-button-size-sm {
    @apply h-7 gap-1 rounded-md px-2 text-xs [&_svg:not([class*='size-'])]:size-3.5;
  }

  .cn-button-size-default {
    @apply h-8 gap-1.5 rounded-lg px-3 text-sm [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-button-size-lg {
    @apply h-9 gap-2 rounded-lg px-3.5 text-sm [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-button-size-icon-xs {
    @apply size-6 rounded-md [&_svg:not([class*='size-'])]:size-3;
  }

  .cn-button-size-icon-sm {
    @apply size-7 rounded-md [&_svg:not([class*='size-'])]:size-3.5;
  }

  .cn-button-size-icon {
    @apply size-8 rounded-lg [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-button-size-icon-lg {
    @apply size-9 rounded-lg [&_svg:not([class*='size-'])]:size-4;
  }

  /* MARK: Button Group */
  .cn-button-group {
    @apply has-[>[data-slot=button-group]]:gap-2 has-[select[aria-hidden=true]:last-child]:[&>[data-slot=select-trigger]:last-of-type]:rounded-e-lg has-[>[data-variant=outline]]:[&>input]:border-neutral-interactive has-[>[data-variant=outline]]:[&>input:focus-visible]:border-primary-interactive-focus has-[>[data-variant=outline]]:*:data-[slot=input-group]:border-neutral-interactive has-[>[data-variant=outline]]:[&>[data-slot=input-group]:has(:focus-visible)]:border-primary-interactive-focus has-[>[data-variant=outline]]:*:data-[slot=select-trigger]:border-neutral-interactive has-[>[data-variant=outline]]:[&>[data-slot=select-trigger]:focus-visible]:border-primary-interactive-focus;
  }

  .cn-button-group-orientation-horizontal {
    @apply flex-row;
  }

  .cn-button-group-orientation-vertical {
    @apply flex-col;
  }

  .cn-button-group-text {
    @apply border-neutral-interactive bg-neutral-interactive/60 text-neutral-text font-medium;
  }

  .cn-button-group-separator {
    @apply bg-neutral-interactive;
  }

  /* MARK: Input */
  .cn-input {
    @apply border bg-clip-padding transition-[background-color,color,border-color,box-shadow] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] selection:bg-primary-fill selection:text-primary-on-fill focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/60 focus-visible:ring-3 aria-invalid:ring-3;
  }

  .cn-input-variant-default {
    @apply border-transparent bg-neutral-interactive/60 text-neutral-text dark:bg-neutral-interactive/50 hover:bg-neutral-interactive dark:hover:bg-neutral-interactive/80 focus-visible:bg-neutral-surface dark:focus-visible:bg-neutral-surface-alt;
  }

  .cn-input-variant-outline {
    @apply border-neutral-interactive bg-neutral-surface text-neutral-text dark:bg-transparent hover:border-neutral-interactive-hover hover:bg-neutral-surface-alt/60 dark:hover:border-neutral-interactive-hover dark:hover:bg-neutral-interactive/30 focus-visible:bg-neutral-surface dark:focus-visible:bg-transparent;
  }

  .cn-input-variant-ghost {
    @apply border-transparent bg-transparent text-neutral-text hover:bg-neutral-interactive/60 dark:hover:bg-neutral-interactive/50 focus-visible:bg-neutral-surface dark:focus-visible:bg-neutral-surface-alt;
  }

  .cn-input-size-xs {
    @apply h-6 rounded-md px-2 text-xs file:h-4 file:text-xs file:font-medium;
  }

  .cn-input-size-sm {
    @apply h-7 rounded-md px-2.5 text-xs file:h-5 file:text-xs file:font-medium;
  }

  .cn-input-size-default {
    @apply h-8 rounded-lg px-3 text-sm file:h-6 file:text-xs file:font-medium;
  }

  .cn-input-size-lg {
    @apply h-9 rounded-lg px-3.5 text-sm file:h-7 file:text-sm file:font-medium;
  }

  /* MARK: Textarea */
  .cn-textarea {
    @apply relative flex w-full min-w-0 flex-col overflow-hidden border bg-clip-padding py-0 outline-none transition-[background-color,color,border-color,box-shadow] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)];
  }

  .cn-textarea-variant-default {
    @apply border-transparent bg-neutral-interactive/60 text-neutral-text dark:bg-neutral-interactive/50 hover:bg-neutral-interactive dark:hover:bg-neutral-interactive/80 has-[:focus-visible]:border-primary-interactive-focus has-[:focus-visible]:bg-neutral-surface dark:has-[:focus-visible]:bg-neutral-surface-alt has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-primary-interactive-focus/30;
  }

  .cn-textarea-variant-outline {
    @apply border-neutral-interactive bg-neutral-surface text-neutral-text dark:bg-transparent hover:border-neutral-interactive-hover hover:bg-neutral-surface-alt/60 dark:hover:border-neutral-interactive-hover dark:hover:bg-neutral-interactive/30 has-[:focus-visible]:border-primary-interactive-focus has-[:focus-visible]:bg-neutral-surface dark:has-[:focus-visible]:bg-transparent has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-primary-interactive-focus/30;
  }

  .cn-textarea-variant-ghost {
    @apply border-transparent bg-transparent text-neutral-text hover:bg-neutral-interactive/60 dark:hover:bg-neutral-interactive/50 has-[:focus-visible]:border-primary-interactive-focus has-[:focus-visible]:bg-neutral-surface dark:has-[:focus-visible]:bg-neutral-surface-alt has-[:focus-visible]:ring-3 has-[:focus-visible]:ring-primary-interactive-focus/30;
  }

  .cn-textarea-size-xs {
    @apply rounded-md text-xs;
  }

  .cn-textarea-size-sm {
    @apply rounded-md text-xs;
  }

  .cn-textarea-size-default {
    @apply rounded-lg text-sm;
  }

  .cn-textarea-size-lg {
    @apply rounded-lg text-sm;
  }

  /* MARK: Select */
  .cn-select-trigger {
    @apply border bg-clip-padding font-medium transition-[background-color,color,border-color,box-shadow] duration-200 ease-[cubic-bezier(0.22,1,0.36,1)] data-placeholder:text-neutral-text-muted data-placeholder:font-normal focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/60 focus-visible:ring-3 aria-invalid:ring-3;
  }

  .cn-select-trigger-variant-default {
    @apply border-transparent bg-neutral-interactive text-neutral-text hover:bg-neutral-interactive-hover active:bg-neutral-interactive-active data-popup-open:bg-neutral-interactive-hover;
  }

  .cn-select-trigger-variant-outline {
    @apply border-neutral-interactive bg-neutral-surface text-neutral-text dark:bg-transparent hover:border-neutral-interactive-hover hover:bg-neutral-interactive dark:hover:bg-neutral-interactive active:bg-neutral-interactive-hover data-popup-open:border-neutral-interactive-hover data-popup-open:bg-neutral-interactive;
  }

  .cn-select-trigger-variant-ghost {
    @apply border-transparent bg-transparent text-neutral-text hover:bg-neutral-interactive active:bg-neutral-interactive-hover data-popup-open:bg-neutral-interactive;
  }

  .cn-select-trigger-size-xs {
    @apply h-6 gap-1 rounded-md px-2 text-xs *:data-[slot=select-value]:gap-1 [&_svg:not([class*='size-'])]:size-3;
  }

  .cn-select-trigger-size-sm {
    @apply h-7 gap-1.5 rounded-md px-2.5 text-xs *:data-[slot=select-value]:gap-1.5 [&_svg:not([class*='size-'])]:size-3.5;
  }

  .cn-select-trigger-size-default {
    @apply h-8 gap-1.5 rounded-lg px-3 text-sm *:data-[slot=select-value]:gap-1.5 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-select-trigger-size-lg {
    @apply h-9 gap-2 rounded-lg px-3.5 text-sm *:data-[slot=select-value]:gap-2 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-select-value {
    @apply flex flex-1 text-start;
  }

  .cn-select-value-aria {
    @apply data-placeholder:text-neutral-text-muted;
  }

  .cn-select-trigger-icon {
    @apply text-neutral-text-muted shrink-0;
  }

  .cn-select-content {
