    @apply size-4 [&_svg:not([class*='size-'])]:size-4;
  }

  .cn-marker-content {
    @apply group-data-[variant=separator]/marker:flex-none group-data-[variant=separator]/marker:text-center *:[a]:hover:text-neutral-text *:[a]:underline *:[a]:underline-offset-3;
  }

  /* MARK: Questionnaire */
  .cn-questionnaire {
    @apply gap-6;
  }

  .cn-questionnaire-progress {
    @apply text-xs;
  }

  .cn-questionnaire-item {
    @apply flex flex-col gap-5;
  }

  .cn-questionnaire-title {
    @apply text-base font-semibold [&:not(:has(~[data-slot=questionnaire-description]))]:mb-5;
  }

  .cn-questionnaire-description {
    @apply text-sm;
  }

  .cn-questionnaire-choices {
    @apply gap-3;
  }

  .cn-questionnaire-choice {
    @apply border-neutral-interactive hover:bg-neutral-interactive/40 data-checked:border-primary-interactive-focus data-checked:bg-primary-interactive data-invalid:border-danger-fill has-[>input:focus-visible]:border-primary-interactive-focus has-[>input:focus-visible]:ring-primary-interactive-focus/50 gap-2.5 rounded-3xl border px-4 py-3 text-sm has-[>input:focus-visible]:ring-3;
  }

  .cn-questionnaire-choice-indicator {
    @apply bg-neutral-interactive group-data-checked/questionnaire-choice:bg-primary-fill dark:group-data-checked/questionnaire-choice:bg-primary-fill group-data-checked/questionnaire-choice:text-primary-on-fill group-data-checked/questionnaire-choice:border-primary-fill size-4 translate-y-[--spacing(0.45)] group-has-data-[slot=questionnaire-choice-description]/questionnaire-choice:translate-y-0.5 rounded-sm border-transparent;
  }

  .cn-questionnaire-choice-indicator-dot {
    @apply bg-primary-on-fill size-2 dark:size-2.5;
  }

  .cn-questionnaire-choice-indicator-check {
    @apply size-3.5;
  }

  .cn-questionnaire-choice-content {
    @apply gap-1;
  }

  .cn-questionnaire-choice-description {
    @apply text-neutral-text-muted;
  }

  .cn-questionnaire-shortcut {
    @apply border-primary-interactive bg-neutral-surface/80 text-neutral-text-muted size-5 translate-y-[--spacing(0.45)] group-has-data-[slot=questionnaire-choice-description]/questionnaire-choice:translate-y-0.5 items-center justify-center rounded-full border font-mono text-[0.625rem] font-medium leading-none;
  }

  .cn-questionnaire-input-wrapper {
    @apply w-full;
  }

  .cn-questionnaire-input {
    @apply bg-neutral-interactive/50 border-transparent focus-visible:border-primary-interactive-focus focus-visible:ring-primary-interactive-focus/30 aria-invalid:ring-danger-interactive-focus/20 dark:aria-invalid:ring-danger-interactive-focus/40 aria-invalid:border-danger-fill dark:aria-invalid:border-danger-fill/50 h-9 rounded-3xl border px-3 py-1 text-base focus-visible:ring-3 aria-invalid:ring-3 md:text-sm;
  }

  .cn-questionnaire-error {
    @apply mt-2 text-sm;
  }

  .cn-questionnaire-actions {
    @apply gap-2 sm:min-h-9;
  }

  /* MARK: Message Scroller */
  .cn-message-scroller-content {
    @apply gap-8;
  }

  /* MARK: Message */
  .cn-message {
    @apply text-sm gap-2;
  }

  .cn-message-avatar {
    @apply min-w-8 group-has-data-[slot=message-footer]/message:-translate-y-8;
  }

  .cn-message-content {
    @apply gap-2.5 group-data-[align=end]/message:*:data-slot:self-end;
  }

  .cn-message-header {
    @apply text-xs font-medium text-neutral-text-muted px-3.5 group-has-data-[variant=ghost]/message:px-0;
  }

  .cn-message-footer {
    @apply text-xs font-medium text-neutral-text-muted px-3.5 group-has-data-[variant=ghost]/message:px-0;
  }

  .cn-message-group {
    @apply gap-2;
  }

  /* MARK: React Aria */
  .cn-alert-dialog-overlay-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 bg-black/30 duration-100 supports-backdrop-filter:backdrop-blur-sm;
  }

  .cn-alert-dialog-content-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text gap-6 rounded-4xl p-6 shadow-xl duration-100 data-[size=default]:max-w-xs data-[size=sm]:max-w-xs data-[size=default]:sm:max-w-md;
  }

  .cn-combobox-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 *:data-[slot=input-group]:bg-neutral-interactive/50 *:data-[slot=input-group]:border-neutral-interactive/30 max-h-72 min-w-36 overflow-hidden rounded-3xl shadow-lg duration-100 *:data-[slot=input-group]:m-1.5 *:data-[slot=input-group]:mb-0 *:data-[slot=input-group]:h-8 *:data-[slot=input-group]:shadow-none;
  }

  .cn-context-menu-content-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text min-w-48 rounded-3xl p-1.5 shadow-lg duration-100;
  }

  .cn-dialog-overlay-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 bg-black/30 duration-100 supports-backdrop-filter:backdrop-blur-sm;
  }

  .cn-dialog-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 grid max-w-[calc(100%-2rem)] gap-6 rounded-4xl p-6 text-sm shadow-xl duration-100 sm:max-w-md;
  }

  .cn-dropdown-menu-content-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text min-w-48 rounded-3xl p-1.5 shadow-lg duration-100;
  }

  .cn-popover-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 flex flex-col gap-4 rounded-3xl p-4 text-sm shadow-lg duration-100;
  }

  .cn-hover-card-content-aria {
    @apply data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text w-72 rounded-3xl p-4 text-sm shadow-lg duration-100;
  }

  .cn-select-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text data-entering:animate-in data-exiting:animate-out data-exiting:fade-out-0 data-entering:fade-in-0 data-exiting:zoom-out-95 data-entering:zoom-in-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 min-w-36 rounded-3xl shadow-lg duration-100;
  }

  .cn-tooltip-content-aria {
    @apply data-entering:animate-in data-entering:fade-in-0 data-entering:zoom-in-95 data-exiting:animate-out data-exiting:fade-out-0 data-exiting:zoom-out-95 data-[placement=bottom]:slide-in-from-top-2 data-[placement=left]:slide-in-from-right-2 data-[placement=right]:slide-in-from-left-2 data-[placement=top]:slide-in-from-bottom-2 inline-flex items-center gap-1.5 rounded-xl px-3 py-1.5 text-xs has-data-[slot=kbd]:pr-1.5 **:data-[slot=kbd]:relative **:data-[slot=kbd]:isolate **:data-[slot=kbd]:z-50 **:data-[slot=kbd]:rounded-lg;
  }

  .cn-context-menu-sub-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text min-w-32 rounded-3xl p-1.5 shadow-lg duration-100;
  }

  .cn-dropdown-menu-sub-content-aria {
    @apply bg-neutral-surface dark:bg-neutral-surface-alt text-neutral-text min-w-36 rounded-3xl p-1.5 shadow-lg duration-100;
  }
}
